func TestAPageEndIsAMilestoneBetweenBlocksOrInsideAParagraph(emonT *testing.T) {
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var ord *port.Cells = port.NewCells()
	var raw *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var fr *port.Cells = port.NewCells()
	var gp *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var t1 *strings.Builder = port.NewText()
	var t2 *strings.Builder = port.NewText()
	var t3 *strings.Builder = port.NewText()
	var t4 *strings.Builder = port.NewText()
	var t5 *strings.Builder = port.NewText()
	// A paragraph that closes its sentence at the end of page 1: the milestone is BETWEEN the blocks.
	ptLine(wd, ln, et, port.TextBlob("a long first line of text"), 1, 7200, 10000, 50000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("ends here."), 1, 7200, 11500, 20000, 12700, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("a new page starts"), 2, 7200, 10000, 50000, 11200, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 2, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "end: well formed")
	ptBrief(t1, nodes, regions, text)
	port.AssertText(emonT, t1, "P1:a long first line of text ends here.;B2;P1:a new page starts;", "a milestone between two blocks")
	// A long last line that does not close a sentence, and a first line at the margin: the paragraph goes on,
	// as `text`, `break`, `text` (one region each).
	ptClear(wd, ln, et)
	ptLine(wd, ln, et, port.TextBlob("first line of text"), 1, 7200, 10000, 50000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("a long line that runs on"), 1, 7200, 11500, 50000, 12700, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("and carries over"), 2, 7200, 10000, 50000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("to its end."), 2, 7200, 11500, 25000, 12700, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 2, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "inline: well formed")
	ptBrief(t2, nodes, regions, text)
	port.AssertText(emonT, t2, "P2:;T:first line of text a long line that runs on ;B2;T:and carries over to its end.;", "a milestone inside a paragraph")
	// A short last line: not a continuation. An indented first line: not one either.
	ptClear(wd, ln, et)
	ptLine(wd, ln, et, port.TextBlob("a long first line of text"), 1, 7200, 10000, 50000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("short"), 1, 7200, 11500, 12000, 12700, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("next page"), 2, 7200, 10000, 30000, 11200, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 2, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "short: well formed")
	ptBrief(t3, nodes, regions, text)
	port.AssertText(emonT, t3, "P1:a long first line of text short;B2;P1:next page;", "a short last line ends the paragraph")
	ptClear(wd, ln, et)
	ptLine(wd, ln, et, port.TextBlob("a long line that runs on"), 1, 7200, 10000, 50000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("and a long last line to go"), 1, 7200, 11500, 50000, 12700, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("indented start"), 2, 9600, 10000, 50000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("then the rest of it"), 2, 7200, 11500, 50000, 12700, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 2, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "indent page: well formed")
	ptBrief(t4, nodes, regions, text)
	port.AssertText(emonT, t4, "P1:a long line that runs on and a long last line to go;B2;P1:indented start then the rest of it;", "an indented first line starts a paragraph")
	// An empty page between: nothing continues across it, and it still has its milestone.
	ptClear(wd, ln, et)
	ptLine(wd, ln, et, port.TextBlob("a long line that runs on"), 1, 7200, 10000, 50000, 11200, 0, 0, 1000)
	ptLine(wd, ln, et, port.TextBlob("on the third"), 3, 7200, 10000, 50000, 11200, 0, 0, 1000)
	port.AssertEq(emonT, ptRun(wd, ln, et, 3, nodes, attrs, regions, text, pages, ledger, layout, ord, raw, tmp, fr, gp, st), 0, "empty page: well formed")
	ptBrief(t5, nodes, regions, text)
	port.AssertText(emonT, t5, "P1:a long line that runs on;B2;B3;P1:on the third;", "an empty page keeps its milestone")
}

